import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 54 Instinct or cleverness?","description":"学习 whatever 与 no matter what，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 54 Instinct or cleverness?","description":"学习 whatever 与 no matter what，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 whatever 与 no matter what，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 53 In the public interest","link":"/life/english/new-concept/book-3/unit-03/lesson-053"},"next":{"text":"第三册：培养技能 · Lesson 55 From the earth: Greetings","link":"/life/english/new-concept/book-3/unit-03/lesson-055"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 53 In the public interest","link":"/life/english/new-concept/book-3/unit-03/lesson-053"},"next":{"text":"第三册：培养技能 · Lesson 55 From the earth: Greetings","link":"/life/english/new-concept/book-3/unit-03/lesson-055"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-054.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-054.md"}'),r={name:"life/english/new-concept/book-3/unit-03/lesson-054.md"};function i(s,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-54-instinct-or-cleverness" tabindex="-1">第三册：培养技能 · Lesson 54 Instinct or cleverness? <a class="header-anchor" href="#第三册-培养技能-·-lesson-54-instinct-or-cleverness" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 54 Instinct or cleverness?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以动物行为的解释为主题，训练从观察到假设的推理。一次成功行为可能来自训练、偶然或环境提示，不宜立即归为聪明或本能。学习疑问词加 ever 的让步结构，在不同解释之间保留空间，并说明什么额外观察可以帮助区分假设。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>instinct</td><td>/ˈɪnstɪŋkt/</td><td>n.</td><td>本能</td><td>animal instinct</td></tr><tr><td>behaviour</td><td>/bɪˈheɪvjə/</td><td>n.</td><td>行为</td><td>observe behaviour</td></tr><tr><td>stimulus</td><td>/ˈstɪmjələs/</td><td>n.</td><td>刺激</td><td>respond to a stimulus</td></tr><tr><td>adapt</td><td>/əˈdæpt/</td><td>v.</td><td>适应</td><td>adapt to change</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>respond to — 对刺激或情况作出反应</li><li>by trial and error — 通过反复试错</li></ul><h2 id="语法讲解-whatever-与-no-matter-what" tabindex="-1">语法讲解：whatever 与 no matter what <a class="header-anchor" href="#语法讲解-whatever-与-no-matter-what" aria-label="Permalink to &quot;语法讲解：whatever 与 no matter what&quot;">​</a></h2><p>whatever 可引导名词性从句，表示任何……的事物，也可引导让步状语从句，表示无论什么。no matter what 通常只用于让步，不能任意替代作宾语的 whatever。however 加形容词或副词可表示无论多么，如 however carefully，但作为连接副词时又可表示转折“然而”。判断功能要看从句是否占据主宾位置，还是为完整主句添加条件让步。讨论行为解释时，让步结构可承认解释未知，同时保留已观察到的事实。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Whatever caused the bird to choose the red lid, one trial cannot establish a general rule.</p></blockquote><p>无论是什么使鸟选择红盖子，一次试验都不能确立普遍规律。</p><p>whatever 从句作让步状语；主句独立成立，强调证据数量的限制。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Take no matter what you need 不符合标准宾语结构，应写 Take whatever you need；no matter what 不能普遍替代 whatever。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 may have 与 rather than，听辨解释的不确定性；遮住最后一句，用自己的话说明如何区分两种解释。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The bird opened the red box first. It may have noticed a food smell rather than the colour. We should switch the boxes and repeat the observation.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句报告虚构动物观察，提出两个解释和后续测试。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>观察与假设分开，后续操作针对气味和颜色这两个变量。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句的一次试验能确立规律吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> 主句明确否定这一推论。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：Choose ___ suits you best.（whatever/no matter what）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> whatever</p><p><strong>解析：</strong> 从句作 choose 的宾语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>改写让步：However carefully we watched, we missed the movement.（用 no matter）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No matter how carefully we watched, we missed the movement.</p><p><strong>解析：</strong> how carefully 保持程度结构。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：whatever 与 no matter what。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-053">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-055">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(r,[["render",i]]);export{u as __pageData,b as default};
